// ── Types ──

export interface FontItem {
  id: string;
  name: string;
  slug: string;
  version?: string;
  license_type: string;
  is_sil_ofl: boolean;
  category: string;
  styles_count: number;
  designers: string[];
  publisher: string;
  api_endpoint?: string;
  web_url?: string;
  download_url?: string;
  github_repo?: string;
  stars?: number;
  npm_package?: string;
  css_font_family?: string;
}

export interface IconLibraryItem {
  id: string;
  name: string;
  tagline: string;
  total_icons: string;
  license: string;
  license_note: string;
  website: string;
  github: string;
  releases_url?: string;
  npm_packages: Record<string, string>;
  cdn_svg_template?: string;
  api_prefix?: string;
  primary_package?: string;
}

export interface ServiceResponseItem {
  id: string;
  category: 'auth_and_sso' | 'ecommerce_and_b2b' | 'developer_and_cloud' | 'schemas';
  categoryTitle: string;
  service: string;
  provider: string;
  documentation_url?: string;
  endpoints?: Record<string, any>;
  responses?: Record<string, {
    description?: string;
    http_status?: number;
    content_type?: string;
    payload?: any;
    data_types?: Record<string, any>;
    headers?: Record<string, any>;
  }>;
  [key: string]: any;
}

// ── Font Helpers ──

export function getAllFonts(): FontItem[] {
  const fontshareList: FontItem[] = (fontshareCatalogRaw as any[]).map(f => ({
    id: f.id || f.slug,
    name: f.name,
    slug: f.slug,
    version: f.version || '1.0',
    license_type: f.license_type === 'itf_ffl' ? 'ITF Free Font' : (f.is_sil_ofl ? 'SIL OFL 1.1' : 'Open Source'),
    is_sil_ofl: !!f.is_sil_ofl,
    category: f.category || 'Sans',
    styles_count: f.styles_count || 1,
    designers: f.designers || [f.publisher || 'Unknown'],
    publisher: f.publisher || 'Fontshare / ITF',
    web_url: f.web_url || `https://www.fontshare.com/fonts/${f.slug}`,
    download_url: f.download_url,
    css_font_family: `'${f.name}', sans-serif`
  }));

  const githubList: FontItem[] = (fontReposRaw as any[]).map(r => {
    const fontName = r.family || r.name || 'Untitled Font';
    const isMono = (r.category || '').toLowerCase().includes('mono');
    const isSerif = (r.category || '').toLowerCase().includes('serif') && !isMono;

    return {
      id: r.repo_id || fontName.toLowerCase().replace(/[^a-z0-9]/g, '-'),
      name: fontName,
      slug: fontName.toLowerCase().replace(/[^a-z0-9]/g, '-'),
      version: 'Latest',
      license_type: r.license || 'SIL OFL 1.1',
      is_sil_ofl: (r.license || '').includes('OFL') || true,
      category: isMono ? 'Monospace' : (isSerif ? 'Serif' : 'Sans'),
      styles_count: r.variable ? 9 : 4,
      designers: [r.owner || 'Community'],
      publisher: r.owner || 'Open Source',
      web_url: r.repository || r.github_url,
      github_repo: r.repository || r.github_url,
      download_url: r.direct_zip_url,
      css_font_family: `'${fontName}', ${isMono ? 'monospace' : 'sans-serif'}`
    };
  });

  return [...fontshareList, ...githubList];
}

// ── Icon Helpers ──

export function getAllIconLibraries(): IconLibraryItem[] {
  return (iconLibrariesRaw as any[]).map(lib => ({
    ...lib,
    primary_package: lib.npm_packages?.react || lib.npm_packages?.vanilla || Object.values(lib.npm_packages || {})[0] || ''
  }));
}

export function getIconNpmPackages(): any {
  return iconPackagesRaw;
}

